{
  "description": "The creature is shown in right-facing side profile against a plain off-white background with a soft shadow beneath its feet. It has a low, elongated, quadrupedal body with a broad, flat, pale gray head that has large round dark eyes with pale blue-gray irises, small nostrils, and a slightly upturned closed mouth. Six pink, feathery, stalk-like external gills extend from the neck just behind the head. The entire dorsal surface from the back of the neck over the back and sides and onto the long tapering tail is covered in overlapping large, rounded, dark brown to tan scales with lighter edges and concentric ridges, while the ventral belly, limbs, and head are pale, smooth, and wrinkled with transverse folds. It stands on four short, thick, stout limbs ending in broad five-toed clawed feet, with the tail extending to the left and cropped by the image edge.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flat and pale gray-blue with smooth, slightly glossy skin, large round eyes with dark pupils and light blue-gray irises, small circular nostrils near the tip of the blunt snout, and a closed mouth with a faint smile; speckled with small dark dots on the cheeks and crown",
      "where": "at the front right end of the body, facing to the right"
    },
    {
      "part": "gills",
      "looks_like": "six pink stalk-like external gills with dense fine feathery filaments along the outer edge, three on each side of the neck; each stalk is pale pink at the base and fringed with darker pink filaments",
      "where": "protruding from the sides of the neck immediately behind the head; three on the near side seen in profile extending outward, three on the far side extending upward above the head"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, rounded keratinous scales/plates in dark brown to gray-brown with tan lighter margins and fine concentric ridges, arranged in diagonal overlapping rows, largest along the mid-back",
      "where": "covering the entire dorsal back, sides, and dorsal surface of the tail from just behind the gills to the tail tip; absent on the head, limbs, and ventral belly"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, muscular limbs with pale gray, wrinkled, slightly glossy skin and loose folds at the joints",
      "where": "two forelegs under the chest behind the head and two hind legs under the rear of the body, supporting the body low to the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad feet with five slender, splayed toes each tipped with a small dark curved claw; pale with wrinkled skin on top",
      "where": "at the distal ends of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, tapering, dorsally covered in the same overlapping dark scales as the back and ventrally pale and smooth, narrowing to a point",
      "where": "extending to the left from the rear of the body, with the tip outside the image frame"
    },
    {
      "part": "markings",
      "looks_like": "small scattered dark gray speckles on the pale skin of the head and neck, and transverse pale wrinkled folds/segments on the ventral belly",
      "where": "speckles on the head and upper neck, folds along the pale underside between the fore and hind legs"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
